// INVERSE side — mappedBy points at Order.user; owns the aggregate lifecycle
package com.bank.mforder.model;

import jakarta.persistence.*;
import java.util.ArrayList;
import java.util.List;

@Entity
@Table(name = "users")
public class User {

    @Id
    @Column(name = "user_id")
    private String userId;

    @Column(name = "full_name", nullable = false)
    private String fullName;

    @Column(nullable = false, unique = true)
    private String email;

    // one user → many orders; cascade+orphanRemoval because orders are owned children
    @OneToMany(mappedBy = "user", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<Order> orders = new ArrayList<>();

    protected User() {}

    public User(String userId, String fullName, String email) {
        this.userId = userId;
        this.fullName = fullName;
        this.email = email;
    }

    // SYNC HELPERS — keep both sides consistent so user_id is never NULL
    public void addOrder(Order order) {
        orders.add(order);
        order.setUser(this);   // owning side set → Hibernate writes user_id
    }

    public void removeOrder(Order order) {
        orders.remove(order);
        order.setUser(null);   // orphanRemoval → DELETE on flush
    }

    public String getUserId() { return userId; }
    public String getFullName() { return fullName; }
    public String getEmail() { return email; }
    public List<Order> getOrders() { return orders; }
}
