// OWNING side — its table holds the user_id FK column
package com.bank.mforder.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "orders")
public class Order {

    @Id
    @Column(name = "order_id")
    private String orderId;

    @ManyToOne(fetch = FetchType.LAZY)   // override default EAGER
    @JoinColumn(name = "user_id")        // FK column on orders table
    private User user;

    @Column(name = "fund_name", nullable = false)
    private String fundName;

    @Column(nullable = false, precision = 15, scale = 4)
    private BigDecimal units;

    @Column(nullable = false, precision = 15, scale = 2)
    private BigDecimal amount;

    @Column(nullable = false)
    private String status;

    protected Order() {}

    public Order(String orderId, String fundName, BigDecimal units, BigDecimal amount) {
        this.orderId = orderId;
        this.fundName = fundName;
        this.units = units;
        this.amount = amount;
        this.status = "PLACED";
    }

    public String getOrderId() { return orderId; }
    public String getFundName() { return fundName; }
    public BigDecimal getUnits() { return units; }
    public BigDecimal getAmount() { return amount; }
    public String getStatus() { return status; }
    public User getUser() { return user; }
    public void setUser(User user) { this.user = user; }
}
