package com.bank.mforder.service;

import com.bank.mforder.dto.UserOrdersView;
import com.bank.mforder.model.Order;
import com.bank.mforder.model.User;
import com.bank.mforder.repository.UserRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.UUID;

@Service
@RequiredArgsConstructor
@Slf4j
public class OrderService {

    private final UserRepository userRepo;

    // Place two orders through the sync helper → cascade inserts both with user_id set
    @Transactional
    public UserOrdersView placeOrders(String userId) {
        User user = userRepo.findById(userId).orElseThrow();

        Order o1 = new Order("ORD-" + shortId(), "NBI Bluechip Fund",
            new BigDecimal("1200.5000"), new BigDecimal("100000"));
        Order o2 = new Order("ORD-" + shortId(), "NBI Liquid Fund",
            new BigDecimal("500.0000"), new BigDecimal("50000"));

        user.addOrder(o1);   // sets o1.user = user → user_id correct
        user.addOrder(o2);

        userRepo.save(user); // cascade ALL → INSERT both orders, user_id='USR-...'
        log.info("Placed 2 orders for {} — cascade inserted children, user_id set", userId);
        return UserOrdersView.from(user);
    }

    // Cancel → orphanRemoval DELETEs the order row
    @Transactional
    public UserOrdersView cancelOrder(String userId, String orderId) {
        User user = userRepo.findWithOrders(userId).orElseThrow();
        user.getOrders().stream()
            .filter(o -> o.getOrderId().equals(orderId))
            .findFirst()
            .ifPresent(user::removeOrder);   // orphanRemoval → DELETE FROM orders
        userRepo.save(user);
        log.info("Cancelled order {} for {} — orphan removed", orderId, userId);
        return UserOrdersView.from(user);
    }

    @Transactional(readOnly = true)
    public UserOrdersView view(String userId) {
        return UserOrdersView.from(userRepo.findWithOrders(userId).orElseThrow());
    }

    private String shortId() { return UUID.randomUUID().toString().substring(0, 6).toUpperCase(); }
}
```

