package com.bank.mforder.controller;

import com.bank.mforder.dto.UserOrdersView;
import com.bank.mforder.service.OrderService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/users")
@RequiredArgsConstructor
public class OrderController {

    private final OrderService service;

    @PostMapping("/{userId}/orders")
    public UserOrdersView place(@PathVariable String userId) {
        return service.placeOrders(userId);
    }

    @DeleteMapping("/{userId}/orders/{orderId}")
    public UserOrdersView cancel(@PathVariable String userId, @PathVariable String orderId) {
        return service.cancelOrder(userId, orderId);
    }

    @GetMapping("/{userId}/orders")
    public UserOrdersView view(@PathVariable String userId) {
        return service.view(userId);
    }
}
