// ─── File: src/test/java/com/bank/mforder/model/UserOrderSyncTest.java ───
package com.bank.mforder.model;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class UserOrderSyncTest {

    @Test
    void addOrderSetsBothSides() {
        User user = new User("USR-RAJESH", "Rajesh Kumar", "rajesh@nbi.com");
        Order order = new Order("ORD-001", "NBI Bluechip Fund",
            new BigDecimal("1200.5000"), new BigDecimal("100000"));

        user.addOrder(order);

        assertThat(user.getOrders()).containsExactly(order);   // inverse side
        assertThat(order.getUser()).isSameAs(user);            // OWNING side → user_id set
    }

    @Test
    void removeOrderClearsOwningSide() {
        User user = new User("USR-RAJESH", "Rajesh Kumar", "rajesh@nbi.com");
        Order order = new Order("ORD-001", "NBI Bluechip Fund",
            new BigDecimal("1200.5000"), new BigDecimal("100000"));
        user.addOrder(order);

        user.removeOrder(order);

        assertThat(user.getOrders()).isEmpty();
        assertThat(order.getUser()).isNull();  // becomes an orphan → DELETE on flush
    }

    @Test
    void mappedByNamesTheOwningField() {
        // @OneToMany(mappedBy="user") → "user" is the FIELD on Order, not a column.
        assertThat("user").isNotEqualTo("user_id");
    }
}
